<script setup lang="ts">
const {cart,loadCart,saveCart,money}=useMarketplace()
onMounted(loadCart)
const total=computed(()=>cart.value.reduce((s,i)=>s+Number(i.price)*i.quantity,0))
function quantity(item:any){item.quantity=Math.max(1,Math.min(Number(item.stock)||1000,Math.floor(Number(item.quantity)||1)));saveCart()}
function remove(id:string){cart.value=cart.value.filter(i=>i.id!==id);saveCart()}
useHead({title:'سبد خرید | پارتلی'})
</script>
<template><section class="shell py-12"><h1 class="market-title">سبد خرید</h1><p class="mb-8 text-sm text-slate-500">قیمت و موجودی کالا هنگام ثبت سفارش دوباره بررسی می‌شود.</p><div v-if="!cart.length" class="market-panel market-empty">سبد خرید شما خالی است.<NuxtLink to="/catalog" class="mt-5 block text-orange">مشاهده قطعات ←</NuxtLink></div><div v-else class="grid gap-6 lg:grid-cols-[1fr_320px]"><div class="market-panel"><article v-for="item in cart" :key="item.id" class="flex flex-wrap items-center justify-between gap-4 border-b py-5"><div><NuxtLink :to="`/products/${item.slug}`" class="font-bold">{{item.name}}</NuxtLink><p class="mt-2 text-sm text-slate-500">{{money(item.price)}}</p></div><div class="flex items-center gap-3"><label class="text-xs">تعداد<input v-model.number="item.quantity" type="number" min="1" :max="item.stock" class="market-input mt-1 w-24" @change="quantity(item)"></label><button class="market-secondary" :aria-label="`حذف ${item.name}`" @click="remove(item.id)">حذف</button></div><strong class="text-sm">{{money(Number(item.price)*item.quantity)}}</strong></article></div><aside class="market-panel h-fit"><h2 class="text-lg font-bold">خلاصه سبد</h2><div class="my-6 flex justify-between gap-3 text-sm"><span>جمع کالاها</span><strong>{{money(total)}}</strong></div><p class="mb-6 text-xs leading-6 text-slate-500">پرداخت در محل. مبلغ و شرایط ارسال در مرحله بعد نمایش داده می‌شود.</p><NuxtLink to="/checkout" class="market-primary w-full">ادامه و ثبت سفارش</NuxtLink><NuxtLink to="/catalog" class="mt-4 block text-center text-sm text-slate-500">ادامه خرید</NuxtLink></aside></div></section></template>
